export const access = "public";

const HTML_B64 = "";

function decodeUtf8Base64(value) {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let out = [];
  for (let i = 0; i < value.length; i += 4) {
    const a = chars.indexOf(value[i]);
    const b = chars.indexOf(value[i + 1]);
    const c = value[i + 2] === "=" ? 0 : chars.indexOf(value[i + 2]);
    const d = value[i + 3] === "=" ? 0 : chars.indexOf(value[i + 3]);
    const n = (a << 18) | (b << 12) | (c << 6) | d;
    out.push((n >> 16) & 255);
    if (value[i + 2] !== "=") out.push((n >> 8) & 255);
    if (value[i + 3] !== "=") out.push(n & 255);
  }
  let binary = "";
  for (const byte of out) binary += String.fromCharCode(byte);
  return decodeURIComponent(escape(binary));
}

const HTML = decodeUtf8Base64(HTML_B64);

export default async function (req, res) {
  res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0");
  res.setHeader("Pragma", "no-cache");
  res.setHeader("Expires", "0");

  // Curiosity V3 handoff: server-render the existing Glow Check entry screen
  // when the CTA carries glow_start=1, so the old landing screen is never
  // painted during the handoff. All existing app markup and functions remain intact.
  const glowStart = String(req.query?.glow_start || "") === "1";
  const initialHTML = glowStart
    ? HTML
        .replace('<section id="s1" class="screen active">', '<section id="s1" class="screen">')
        .replace('<section id="s2" class="screen">', '<section id="s2" class="screen active">')
    : HTML;

  res.send(initialHTML);
}